# Parabola y^2 = -12x, point P = (0, 6).
# Vertical line x=0: y^2 = 0 -> exactly one common point.
vertical_points = {y for y in [0] if y * y == 0}  # y^2 = -12*0 -> y=0 only
count_vertical = 1 if len(vertical_points) == 1 else 0

# Non-vertical lines y = kx + 6:
# (kx+6)^2 = -12x -> k^2 x^2 + (12k+12) x + 36 = 0
def num_solutions(k):
    a = k * k
    b = 12 * k + 12
    c = 36
    if a == 0:
        # linear: b x + c = 0
        return 1 if b != 0 else (0 if c != 0 else None)
    d = b * b - 4 * a * c
    return 2 if d > 0 else (1 if d == 0 else 0)

# k = 0 case
k_values = []
